ON CONFLICT DO NOTHING;

UPDATE bag_listings l
   SET quantity_remaining = GREATEST(l.quantity_total - COALESCE((
           SELECT SUM(r.quantity) FROM reservations r
            WHERE r.listing_id = l.id AND r.status IN ('pending_pickup', 'picked_up')), 0), 0)
 WHERE l.id::text LIKE 'd1d1d1d1-%';

UPDATE bag_listings SET status = 'sold_out'
 WHERE id::text LIKE 'd1d1d1d1-%' AND status = 'published' AND quantity_remaining = 0;
